<?php
include '../includes/auth.php';include '../db.php';include 'purchase_helpers.php';
$id=(int)($_GET['id']??0);if($id<=0){header('Location:purchases.php');exit;}$msg='';$msgType='';
if(isset($_POST['receive_purchase'])){try{receivePurchase($conn,$id,(int)$_SESSION['user_id']);$msg='Purchase received. Inventory and weighted product costs were updated.';$msgType='success';}catch(Throwable $e){$msg=$e->getMessage();$msgType='error';}}
if(isset($_POST['add_payment'])){$amount=max(0,(float)($_POST['amount']??0));$date=$_POST['payment_date']??date('Y-m-d');$method=trim($_POST['payment_method']??'Cash');$reference=trim($_POST['reference_no']??'');$notes=trim($_POST['payment_notes']??'');$row=$conn->query("SELECT total_amount-paid_amount balance,status FROM purchases WHERE purchase_id=$id")->fetch_assoc();if(!$row||$row['status']==='cancelled'){$msg='Payments cannot be added to this purchase.';$msgType='error';}elseif($amount<=0||$amount>(float)$row['balance']+0.005){$msg='Enter an amount up to the outstanding balance.';$msgType='error';}else{$uid=(int)$_SESSION['user_id'];$s=$conn->prepare("INSERT INTO purchase_payments (purchase_id,payment_date,amount,payment_method,reference_no,notes,added_by) VALUES (?,?,?,?,NULLIF(?,''),NULLIF(?,''),?)");$s->bind_param('isdsssi',$id,$date,$amount,$method,$reference,$notes,$uid);$s->execute();$s->close();refreshPurchasePaymentStatus($conn,$id);$msg='Supplier payment recorded.';$msgType='success';}}
if(isset($_POST['cancel_purchase'])){$p=$conn->query("SELECT status,paid_amount FROM purchases WHERE purchase_id=$id")->fetch_assoc();if($p&&$p['status']==='draft'&&(float)$p['paid_amount']==0){$conn->query("UPDATE purchases SET status='cancelled' WHERE purchase_id=$id");$msg='Draft purchase cancelled.';$msgType='warning';}else{$msg='Only unpaid draft purchases can be cancelled.';$msgType='error';}}
$s=$conn->prepare("SELECT p.*,s.supplier_name,s.supplier_code,s.contact_person,s.phone,s.email,s.address,uc.full_name created_name,ur.full_name received_name FROM purchases p JOIN suppliers s ON s.supplier_id=p.supplier_id LEFT JOIN users uc ON uc.user_id=p.created_by LEFT JOIN users ur ON ur.user_id=p.received_by WHERE p.purchase_id=?");$s->bind_param('i',$id);$s->execute();$purchase=$s->get_result()->fetch_assoc();$s->close();if(!$purchase){http_response_code(404);die('Purchase not found.');}
$items=$conn->query("SELECT pi.*,p.product_name,p.sku,p.unit,p.stock_qty FROM purchase_items pi JOIN products p ON p.product_id=pi.product_id WHERE pi.purchase_id=$id ORDER BY pi.purchase_item_id");$payments=$conn->query("SELECT pp.*,u.full_name FROM purchase_payments pp LEFT JOIN users u ON u.user_id=pp.added_by WHERE pp.purchase_id=$id ORDER BY pp.payment_date DESC,pp.payment_id DESC");$balance=(float)$purchase['total_amount']-(float)$purchase['paid_amount'];
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo htmlspecialchars($purchase['purchase_number']);?> - Purchase</title><link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Lora:wght@600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><style><?php include 'shared_style.php';include 'erp_style.php';?>.detail-grid{display:grid;grid-template-columns:1fr 380px;gap:18px;align-items:start}.document-head{display:flex;justify-content:space-between;gap:25px;padding:20px}.document-head h2{font:700 22px 'Lora',serif}.doc-meta{text-align:right;line-height:1.7}.supplier-box{background:var(--bg);padding:14px;border-radius:8px;line-height:1.6}.payment-list{padding:0 18px 12px}.payment-row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--border)}.payment-row:last-child{border:0}.print-header{display:none}@media(max-width:950px){.detail-grid{grid-template-columns:1fr}}@media print{@page{size:A4;margin:12mm}.sidebar,.topbar,.no-print{display:none!important}.main{margin:0}.content{padding:0}.detail-grid{display:block}.detail-grid>aside{display:none}.card{box-shadow:none;border:0}.print-header{display:flex;align-items:center;gap:12px;border-bottom:3px solid #0f766e;padding-bottom:10px;margin-bottom:15px}.print-header img{width:62px}.document-head{padding:10px 0}.table-card-full{margin-top:10px}th{background:#e8f4f2!important}tr{break-inside:avoid}.report-footer{display:flex!important}}</style></head><body>
<?php include 'shared_nav.php';?><main class="main"><?php include 'shared_topbar.php';?><div class="content"><div class="print-header"><img src="../supun-logo.png"><div><h2>Supun Group of Companies</h2><strong>Purchase Document</strong></div></div><div class="page-header no-print"><div><h1 class="page-title-h"><i class="fa-solid fa-file-invoice"></i> <?php echo htmlspecialchars($purchase['purchase_number']);?></h1><p class="page-sub">Purchase details, stock receipt and supplier payments</p></div><div class="quick-links"><a class="btn-secondary" href="purchases.php"><i class="fa-solid fa-arrow-left"></i> Purchases</a><button class="btn-secondary" onclick="print()"><i class="fa-solid fa-print"></i> Print</button></div></div>
<?php if($msg):?><div class="alert <?php echo $msgType;?> no-print"><?php echo htmlspecialchars($msg);?></div><?php endif;?>
<div class="detail-grid"><div><section class="card"><div class="document-head"><div><h2><?php echo htmlspecialchars($purchase['purchase_number']);?></h2><div class="supplier-box"><strong><?php echo htmlspecialchars($purchase['supplier_name']);?></strong><br><?php echo nl2br(htmlspecialchars($purchase['address']?:''));?><br><?php echo htmlspecialchars($purchase['phone']?:'');?></div></div><div class="doc-meta"><strong>Purchase Date:</strong> <?php echo date('d M Y',strtotime($purchase['purchase_date']));?><br><strong>Supplier Invoice:</strong> <?php echo htmlspecialchars($purchase['supplier_invoice']?:'-');?><br><strong>Stock Status:</strong> <span class="status-pill <?php echo $purchase['status'];?>"><?php echo $purchase['status'];?></span><br><strong>Payment:</strong> <span class="status-pill <?php echo $purchase['payment_status'];?>"><?php echo $purchase['payment_status'];?></span></div></div><div class="tbl-wrap"><table><thead><tr><th>SKU</th><th>Product</th><th>Ordered</th><th>Received</th><th>Unit Cost</th><th>Total</th></tr></thead><tbody><?php while($i=$items->fetch_assoc()):?><tr><td><?php echo htmlspecialchars($i['sku']?:'-');?></td><td><strong><?php echo htmlspecialchars($i['product_name']);?></strong></td><td><?php echo number_format((float)$i['quantity'],0).' '.htmlspecialchars($i['unit']);?></td><td><?php echo number_format((float)$i['received_qty'],0);?></td><td class="money">Rs. <?php echo number_format((float)$i['unit_cost'],2);?></td><td class="money">Rs. <?php echo number_format((float)$i['line_total'],2);?></td></tr><?php endwhile;?></tbody></table></div><div class="totals-box"><div class="total-row-flex"><span>Subtotal</span><strong>Rs. <?php echo number_format((float)$purchase['subtotal'],2);?></strong></div><div class="total-row-flex"><span>Discount</span><strong>- Rs. <?php echo number_format((float)$purchase['discount'],2);?></strong></div><div class="total-row-flex"><span>Tax / Other</span><strong>Rs. <?php echo number_format((float)$purchase['tax'],2);?></strong></div><div class="total-row-flex grand"><span>Total</span><strong>Rs. <?php echo number_format((float)$purchase['total_amount'],2);?></strong></div><div class="total-row-flex"><span>Paid</span><strong>Rs. <?php echo number_format((float)$purchase['paid_amount'],2);?></strong></div><div class="total-row-flex"><span>Balance</span><strong>Rs. <?php echo number_format($balance,2);?></strong></div></div></section>
<section class="card table-card-full" style="margin-top:18px"><div class="card-head"><h4><i class="fa-solid fa-money-check-dollar"></i> Payment History</h4></div><div class="payment-list"><?php if(!$payments->num_rows):?><div class="empty-row">No supplier payments recorded.</div><?php endif;?><?php while($pay=$payments->fetch_assoc()):?><div class="payment-row"><div><strong><?php echo date('d M Y',strtotime($pay['payment_date']));?> - <?php echo htmlspecialchars($pay['payment_method']);?></strong><div class="muted"><?php echo htmlspecialchars($pay['reference_no']?:'No reference');?> &bull; <?php echo htmlspecialchars($pay['full_name']?:'System');?></div></div><strong class="money">Rs. <?php echo number_format((float)$pay['amount'],2);?></strong></div><?php endwhile;?></div></section></div>
<aside class="no-print"><?php if($purchase['status']==='draft'):?><section class="card" style="margin-bottom:18px"><div class="card-head"><h4><i class="fa-solid fa-box-open"></i> Receive Stock</h4></div><div class="erp-form"><p class="muted">Receiving increases inventory and recalculates weighted average product cost. This cannot be repeated.</p><form method="post"><button class="btn-primary" name="receive_purchase" style="width:100%;justify-content:center;margin-top:12px" onclick="return confirm('Receive all products into stock?')"><i class="fa-solid fa-warehouse"></i> Receive All Stock</button></form><form method="post"><button class="btn-small" name="cancel_purchase" style="width:100%;justify-content:center;margin-top:8px" onclick="return confirm('Cancel this draft?')">Cancel Draft</button></form></div></section><?php endif;?>
<?php if($balance>0&&$purchase['status']!=='cancelled'):?><section class="card"><div class="card-head"><h4><i class="fa-solid fa-hand-holding-dollar"></i> Record Supplier Payment</h4></div><form method="post" class="erp-form"><div class="field"><label>Outstanding Balance</label><input class="inp" value="Rs. <?php echo number_format($balance,2);?>" disabled></div><div class="field" style="margin-top:10px"><label>Amount *</label><input class="inp" type="number" name="amount" min="0.01" max="<?php echo $balance;?>" step="0.01" required></div><div class="field" style="margin-top:10px"><label>Payment Date</label><input class="inp" type="date" name="payment_date" value="<?php echo date('Y-m-d');?>" required></div><div class="field" style="margin-top:10px"><label>Method</label><select class="inp" name="payment_method"><option>Cash</option><option>Bank Transfer</option><option>Cheque</option><option>Card</option></select></div><div class="field" style="margin-top:10px"><label>Reference</label><input class="inp" name="reference_no"></div><div class="field" style="margin-top:10px"><label>Note</label><textarea class="inp" name="payment_notes"></textarea></div><button class="btn-primary" name="add_payment" style="width:100%;justify-content:center;margin-top:12px"><i class="fa-solid fa-plus"></i> Add Payment</button></form></section><?php endif;?></aside></div><div class="report-footer"><span>Supun Group of Companies</span><span>Computer-generated purchase document</span></div>
